import{c as t,Q as r,j as o,m as a}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"MCP 2026-07-28 規格更新與 Claude 支援","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/49-mcp-2026-07-28.md","filePath":"research/best-practices/49-mcp-2026-07-28.md","lastUpdated":1785909234000}'),d={name:"research/best-practices/49-mcp-2026-07-28.md"};function s(c,e,l,n,i,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="mcp-2026-07-28-規格更新與-claude-支援" tabindex="-1">MCP 2026-07-28 規格更新與 Claude 支援 <a class="header-anchor" href="#mcp-2026-07-28-規格更新與-claude-支援" aria-label="Permalink to &quot;MCP 2026-07-28 規格更新與 Claude 支援&quot;">​</a></h1><blockquote><p>來源：<a href="https://claude.com/blog/bringing-mcp-2026-07-28-to-claude" target="_blank" rel="noreferrer">Bringing MCP 2026-07-28 to Claude</a>（2026-07-28） 整理日期：2026-08-04 基礎：<code>14-mcp.md</code>（transport / scope / OAuth / Tool Search 完整指南）——本檔只記本次規格增量。</p></blockquote><hr><h2 id="這版改了什麼-mcp-第五個規格版本" tabindex="-1">這版改了什麼（MCP 第五個規格版本） <a class="header-anchor" href="#這版改了什麼-mcp-第五個規格版本" aria-label="Permalink to &quot;這版改了什麼（MCP 第五個規格版本）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>變更</th><th>意義</th></tr></thead><tbody><tr><td>1</td><td><strong>Stateless core</strong></td><td>從雙向有狀態協定改為 request/response 模型；server 可直接部署在 serverless / edge，擴展與部署大幅簡化</td></tr><tr><td>2</td><td><strong>Extensions 框架標準化</strong></td><td>MCP Apps 與 Tasks 以<strong>版本化 extension</strong> 出貨，新增能力不必動核心協定</td></tr><tr><td>3</td><td><strong>Authorization 對齊 OAuth 2.0 / OIDC</strong></td><td>可直接接 Entra、Okta 等既有 IdP，不再需要 workaround</td></tr><tr><td>4</td><td><strong>MCP Apps（互動 UI）</strong></td><td>server 可在對話中直接算繪互動元件，免切分頁</td></tr><tr><td>5</td><td><strong>Tasks</strong></td><td>長時間執行工作的標準化表達</td></tr><tr><td>6</td><td><strong>企業託管存取</strong></td><td>管理員透過 IdP 佈建 connector，群組繼承存取權，終端使用者零設定</td></tr></tbody></table><p><strong>Claude 端</strong>：Claude 產品線已支援上述能力，可用 MCP server 超過 950 個；已發布的 connector 取得 dashboard，可看效能、採用、錯誤與跨產品使用量。</p><hr><h2 id="claude-code-端的相關行為-同期-changelog" tabindex="-1">Claude Code 端的相關行為（同期 changelog） <a class="header-anchor" href="#claude-code-端的相關行為-同期-changelog" aria-label="Permalink to &quot;Claude Code 端的相關行為（同期 changelog）&quot;">​</a></h2><ul><li>MCP 工具呼叫超過 <strong>2 分鐘自動轉背景</strong>，session 保持可用（<code>CLAUDE_CODE_MCP_AUTO_BACKGROUND_MS</code> 可調，v2.1.212）</li><li>MCP 重新認證不再先撤銷可用憑證再登入（v2.1.216）</li><li>修正 <code>--mcp-config</code> 的 server 在 print 模式（<code>-p</code>）首輪前未連上，導致模型把工具呼叫吐成純文字（v2.1.213）</li><li>修正 OAuth MCP server 在 token refresh 後仍要求重新授權（v2.1.206）、per-server <code>request_timeout_ms</code> 被忽略（v2.1.206）</li><li>session 工作目錄會出現在 MCP <code>roots/list</code>（v2.1.203）</li></ul><hr><h2 id="對本-workspace-的影響" tabindex="-1">對本 workspace 的影響 <a class="header-anchor" href="#對本-workspace-的影響" aria-label="Permalink to &quot;對本 workspace 的影響&quot;">​</a></h2><ul><li><strong>Deferred tool loading 紀律不變</strong>：未取 schema 前不可呼叫（<code>context-management.md</code>）。stateless core 不改變這點，但讓自建 server 更容易部署。</li><li>自建 MCP server 若原本依賴長連線的雙向通知，需檢視是否要遷移到 Tasks extension。</li><li>互動式驗證的 MCP server（如 claude.ai connector）在 headless / cron 執行中可能不可用——<code>Workflow</code> 的既有 caveat 依舊成立。</li></ul><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><code>14-mcp.md</code> — MCP 整合完整指南（transport / scope / OAuth / Managed MCP）</li><li><code>48-w28-w31-features.md</code> — 同期 Claude Code 變更</li></ul>',15)])])}const g=t(d,[["render",s]]);export{p as __pageData,g as default};
